import { html } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { until } from 'lit/directives/until.js';
export default function squizStoryRenderer(main) {
    const renderer = (input, info) => {
        const renderAsync = async () => {
            let markup = '';
            try {
                markup = await main(input, info);
            }
            catch (err) {
                markup = `<pre data-edge-error style="color:#b00">${String(err)}</pre>`;
            }
            return html `${unsafeHTML(markup)}`;
        };
        return html `${until(renderAsync())}`;
    };
    renderer.markup = async (input, info) => await main(input, info);
    return renderer;
}
